<?php
// Read-only, bounded lookup of active foreign-key IDs for the downloaded template.
require_role('admin');$referenceSearch=input_text($_GET,'ref_q',100,false);
$referenceTable=$module==='siswa'?'kelas':'jurusan';$referenceKey=$module==='siswa'?'id_kelas':'id_jurusan';$referenceName=$module==='siswa'?'nama_kelas':'nama_jurusan';
$where="status='aktif'";$args=[];if($referenceSearch!==''){$where.=' AND (`'.$referenceName.'` LIKE ? OR CAST(`'.$referenceKey.'` AS CHAR)=?)';$args=['%'.$referenceSearch.'%',$referenceSearch];}
$referenceTotal=(int)ak_query('SELECT COUNT(*) FROM `'.$referenceTable.'` WHERE '.$where,$args)->fetchColumn();[$referencePage,$referencePages,$referenceOffset]=crud_page_bounds($referenceTotal,20,'ref_page');
$referenceRows=ak_rows('SELECT `'.$referenceKey.'` id,`'.$referenceName.'` nama FROM `'.$referenceTable.'` WHERE '.$where.' ORDER BY `'.$referenceName.'` LIMIT '.crud_page_limit('ref_page').' OFFSET '.$referenceOffset,$args);
?><section class="panel" data-import-reference><h2>Referensi <?=e($referenceTable)?> untuk template</h2><p>Isi kolom <strong><?=e($referenceKey)?></strong> menggunakan ID aktif di bawah. Nomor ini menghubungkan data dengan database; bukan nomor urut baris Excel.</p><form method="get" class="form-grid filter"><?php ak_hidden('view','impor');ak_hidden('module',$module);ak_field('ref_q','Cari nama / ID',$referenceSearch,'search',false);?><button class="secondary">Cari referensi</button></form><div class="table-scroll"><table><thead><tr><th><?=e($referenceKey)?></th><th>Nama</th></tr></thead><tbody><?php foreach($referenceRows as $reference):?><tr><td><?=e($reference['id'])?></td><td class="wrap"><?=e($reference['nama'])?></td></tr><?php endforeach;if(!$referenceRows):?><tr><td colspan="2">Referensi tidak ditemukan.</td></tr><?php endif;?></tbody></table></div><?php crud_pager($referencePage,$referencePages,$referenceTotal,'referensi','ref_page');?></section>
